CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid()); CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END; $$;
CREATE TRIGGER create_profile_after_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','event_manager','scanner','user')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin'); $$;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated;
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, category text NOT NULL, description text NOT NULL DEFAULT '', price_minor integer NOT NULL CHECK(price_minor>=0), currency text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), image_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_public ON public.products FOR SELECT TO anon,authenticated USING(status='published'); CREATE POLICY products_admin ON public.products FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.product_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, sku text NOT NULL UNIQUE, size text, color text, stock integer NOT NULL DEFAULT 0 CHECK(stock>=0));
GRANT SELECT ON public.product_variants TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_variants TO authenticated; GRANT ALL ON public.product_variants TO service_role; ALTER TABLE public.product_variants ENABLE ROW LEVEL SECURITY;
CREATE POLICY variants_public ON public.product_variants FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND p.status='published')); CREATE POLICY variants_admin ON public.product_variants FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, event_date date, venue text, description text NOT NULL DEFAULT '', capacity integer CHECK(capacity>0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','cancelled','completed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.events TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.events TO authenticated; GRANT ALL ON public.events TO service_role; ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_public ON public.events FOR SELECT TO anon,authenticated USING(status='published'); CREATE POLICY events_admin ON public.events FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.membership_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE UNIQUE, motivation text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','suspended')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.membership_applications TO authenticated; GRANT UPDATE,DELETE ON public.membership_applications TO authenticated; GRANT ALL ON public.membership_applications TO service_role; ALTER TABLE public.membership_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_owner_read ON public.membership_applications FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY membership_owner_insert ON public.membership_applications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending'); CREATE POLICY membership_admin ON public.membership_applications FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE INDEX events_status_idx ON public.events(status); CREATE INDEX products_status_category_idx ON public.products(status,category);